export function buildAction05Prompt(input: Action05Input): string {
  const issueCount = input.extractedIssueData.length;
  const categories = new Set(input.extractedIssueData.map(i => i.category));
  const priorities = new Set(input.extractedIssueData.map(i => i.priority));

  const timeSeriesAnalysis = analyzeTimeSeries(input.extractedIssueData);
  const recurrencePatterns = input.analysisParameters.includeRecurrenceAnalysis
    ? identifyRecurrencePatterns(input.extractedIssueData)
    : [];

  const prompt = `# Action 05: 可視化レポート生成

## 入力データ
- 抽出済み課題数: ${issueCount}
- 課題カテゴリ: ${Array.from(categories).join(", ")}
- 優先度レベル: ${Array.from(priorities).join(", ")}
- 分析期間: ${input.analysisParameters.timeGranularity}

## 時系列分析結果
${timeSeriesAnalysis.map(ts => `- ${ts.period}: ${ts.count}件 (解決率: ${ts.resolutionRate}%)`).join("\n")}

## 再発パターン分析
${recurrencePatterns.length > 0
  ? recurrencePatterns.map(rp => `- ${rp.issueType}: ${rp.occurrenceCount}回 (トレンド: ${rp.trend})`).join("\n")
  : "- 再発パターンなし"}

## 生成タスク
1. 時系列データから課題トレンドを可視化
2. カテゴリ別の課題分布を分析
3. ボトルネック変化パターンを特定
4. 優先度の高い課題を強調表示
5. 異常値と新規パターンを検出
6. 改善施策を提案

## 出力要件
- 複数の視点からの可視化チャート
- 主要な発見と洞察
- 優先度付きの推奨アクション
- データ品質評価
- エスカレーション対象の特定

## 品質基準
- データ品質スコア: ${input.analysisParameters.highlightThreshold}以上
- 信頼度レベル: 70%以上
- 異常値検出: 自動フラグ付け`;

  return prompt;
}

function analyzeTimeSeries(
  issues: Array<{ reportedDate: string; status: string }>
): Array<{ period: string; count: number; resolutionRate: number }> {
  const periodMap = new Map<string, { total: number; resolved: number }>();

  for (const issue of issues) {
    const date = new Date(issue.reportedDate);
    const period = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;

    if (!periodMap.has(period)) {
      periodMap.set(period, { total: 0, resolved: 0 });
    }

    const stats = periodMap.get(period)!;
    stats.total += 1;
    if (issue.status === "resolved" || issue.status === "closed") {
      stats.resolved += 1;
    }
  }

  return Array.from(periodMap.entries())
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([period, stats]) => ({
      period,
      count: stats.total,
      resolutionRate: Math.round((stats.resolved / stats.total) * 100),
    }));
}

function identifyRecurrencePatterns(
  issues: Array<{ title: string; category: string; reportedDate: string }>
): Array<{
  issueType: string;
  occurrenceCount: number;
  lastOccurrence: string;
  trend: "increasing" | "decreasing" | "stable";
}> {
  const categoryOccurrences = new Map<string, string[]>();

  for (const issue of issues) {
    if (!categoryOccurrences.has(issue.category)) {
      categoryOccurrences.set(issue.category, []);
    }
    categoryOccurrences.get(issue.category)!.push(issue.reportedDate);
  }

  const patterns: Array<{
    issueType: string;
    occurrenceCount: number;
    lastOccurrence: string;
    trend: "increasing" | "decreasing" | "stable";
  }> = [];

  for (const [category, dates] of categoryOccurrences.entries()) {
    if (dates.length > 1) {
      const sortedDates = dates.sort();
      const lastOccurrence = sortedDates[sortedDates.length - 1];

      // 簡易的なトレンド判定: 最後の3件を見て判定
      const recentCount = dates.filter(
        d => new Date(d).getTime() > Date.now() - 7 * 24 * 60 * 60 * 1000
      ).length;
      const olderCount = dates.filter(
        d => new Date(d).getTime() <= Date.now() - 7 * 24 * 60 * 60 * 1000
      ).length;

      let trend: "increasing" | "decreasing" | "stable" = "stable";
      if (recentCount > olderCount * 1.2) {
        trend = "increasing";
      } else if (recentCount < olderCount * 0.8) {
        trend = "decreasing";
      }

      patterns.push({
        issueType: category,
        occurrenceCount: dates.length,
        lastOccurrence,
        trend,
      });
    }
  }

  return patterns.sort((a, b) => b.occurrenceCount - a.occurrenceCount);
}
